import type { MarkPrinciple, MarkStep, Question } from "../../../types.ts";

type Diff = Question["difficulty"];
type Paper = NonNullable<Question["paper"]>;
type Kind = MarkPrinciple["kind"];
type Code = MarkStep["markCode"];

type McqSpec = [string, string[], number, Diff, Paper, Kind, string, string, string, string];
type NumPart = [string, number, string?];
type NumSpec = [string, NumPart[], Diff, Paper, Kind, string, string, string[], string, string];
type OpenPart = [string, string, number, string[]];
type OpenSpec = [string, OpenPart[], Diff, Paper, Kind, string, string, string, string];
type ConceptSpec = { mcq: McqSpec[]; num: NumSpec[]; open: OpenSpec[] };

const LETTERS = ["a", "b", "c", "d"] as const;
const CODES = ["M", "A", "R", "B"] as const;

function principle(kind: Kind, name: string, statement: string): MarkPrinciple {
  return { kind, name, statement };
}

const MCQ_SPECIAL = /all of the (above|these)|none of the (above|these)|none of these|\b[abcd]\s+and\s+[abcd]\b/i;
const mcqSeed = (s: string): number => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
};
const mcqOrder = (texts: readonly string[], seed: string): number[] | null => {
  if (texts.some((t) => MCQ_SPECIAL.test(t))) return null;
  let a = mcqSeed(seed);
  const rnd = () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const order = texts.map((_, i) => i);
  for (let i = order.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  return order.every((v, i) => v === i) && order.length > 1 ? [order[1], order[0], ...order.slice(2)] : order;
};
const letterOf = (i: number): string => String.fromCharCode(97 + i);
const letterMapOf = (order: number[]): Record<string, string> =>
  Object.fromEntries(order.map((oldI, pos) => [letterOf(oldI), letterOf(pos)]));
const remapLetters = (s: string, map: Record<string, string> | null): string =>
  map ? s.replace(/\(([abcd])\)/g, (m, L) => (map[L] ? "(" + map[L] + ")" : m)) : s;

function mkMcq(prefix: string, n: number, s: McqSpec): Question {
  const [stem, choicesRaw, correctRaw, difficulty, paper, kind, name, statement, reason, error] = s;
  const __o = mcqOrder(choicesRaw, `${prefix}${n}`);
  const choices = __o ? __o.map((i) => choicesRaw[i]) : choicesRaw;
  const correct = __o ? __o.indexOf(correctRaw) : correctRaw;
  const correctId = LETTERS[correct];
  return {
    id: `${prefix}${n}`,
    difficulty,
    paper,
    totalMarks: 2,
    stem,
    response: { type: "mcq", choices: choices.map((text, i) => ({ id: LETTERS[i], text })), correctChoiceId: correctId },
    markscheme: {
      principles: [principle(kind, name, statement)],
      steps: [
        { reasoning: reason, marks: 1, markCode: "M" },
        { reasoning: `Therefore choice (${correctId}) is correct.`, marks: 1, markCode: "A" },
      ],
      finalAnswer: `**(${correctId})** ${choices[correct]}`,
      commonErrors: [error],
    },
  };
}

function mkNumeric(prefix: string, n: number, s: NumSpec): Question {
  const [stem, parts, difficulty, paper, kind, name, statement, reasons, final, error] = s;
  return {
    id: `${prefix}${n}`,
    difficulty,
    paper,
    totalMarks: parts.length,
    stem,
    response: { type: "numeric", parts: parts.map(([label, answer, unit]) => ({ label, answer, ...(unit ? { unit } : {}) })) },
    markscheme: {
      principles: [principle(kind, name, statement)],
      steps: reasons.map((reasoning) => ({ reasoning, marks: 1, markCode: "M" as Code })),
      finalAnswer: final,
      commonErrors: [error],
    },
  };
}

function mkOpen(prefix: string, n: number, s: OpenSpec): Question {
  const [stem, parts, difficulty, paper, kind, name, statement, final, error] = s;
  const steps = parts.flatMap(([label, , marks, reasons]) => reasons.map((reasoning, j) => ({ part: label, reasoning, marks: 1, markCode: CODES[j] as Code })));
  return {
    id: `${prefix}${n}`,
    difficulty,
    paper,
    totalMarks: parts.reduce((sum, p) => sum + p[2], 0),
    stem,
    parts: parts.map(([label, prompt, marks]) => ({ label, prompt, marks })),
    response: { type: "open" },
    markscheme: { principles: [principle(kind, name, statement)], steps, finalAnswer: final, commonErrors: [error] },
  };
}

function build(prefix: string, spec: ConceptSpec): Question[] {
  return [...spec.mcq.map((s, i) => mkMcq(prefix, i + 5, s)), ...spec.num.map((s, i) => mkNumeric(prefix, i + 10, s)), ...spec.open.map((s, i) => mkOpen(prefix, i + 15, s))];
}

